import AppKit
import SwiftUI

/// Official AionUi app artwork, displayed as a white badge with a black mark.
/// The embedded PNG is unchanged; the view inverts its monochrome colors and
/// enlarges the mark inside the original badge footprint.
/// Source: iOfficeAI/AionUi@c140550d04e44f3d6f8a9830b40ae56e4689a977/resources/icon.png
/// SHA256: 091061e2ca50ea8b789e3109ca4e61038e9239e8a0405211ab45a89f0e492c6b
/// Repository license and attribution: third-party-licenses/AionUi-Apache-2.0.txt.
@MainActor
struct AionUiTeamIcon: View {
    let size: CGFloat

    var body: some View {
        Group {
            if let image = Self.image {
                Image(nsImage: image)
                    .renderingMode(.original)
                    .resizable()
                    .interpolation(.high)
                    .aspectRatio(contentMode: .fit)
                    .colorInvert()
                    .scaleEffect(1.35)
            } else {
                Image(systemName: "person.3.fill")
                    .font(.system(size: size * 0.8, weight: .semibold))
                    .foregroundStyle(.secondary)
            }
        }
        .frame(width: size, height: size)
        .clipShape(RoundedRectangle(cornerRadius: size * 0.15))
        .accessibilityLabel("AionUi Team")
    }

    private static let image: NSImage? = {
        guard let data = Data(base64Encoded: pngBase64) else { return nil }
        return NSImage(data: data)
    }()

    private static let pngBase64 = ""
}
